import { beforeEach, describe, expect, it, vi } from 'vitest';
import { NextRequest } from 'next/server';
import { POST } from '../../app/api/token/route';
import { model } from '../oauth/model';

vi.mock('../oauth/model', () => ({
  model: {
    getClient: vi.fn(),
    getAuthorizationCode: vi.fn(),
    saveToken: vi.fn(),
    saveRefreshToken: vi.fn(),
    revokeAuthorizationCode: vi.fn(),
    getRefreshToken: vi.fn(),
    getAccessToken: vi.fn(),
    deleteToken: vi.fn(),
    deleteRefreshToken: vi.fn(),
  },
}));

vi.mock('../analytics/analytics', () => ({
  identify: vi.fn(),
  flushAnalytics: vi.fn().mockResolvedValue(undefined),
}));

describe('/api/token route integration', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('persists authorization-code grant context onto saved access token', async () => {
    const client = {
      id: 'client-123',
      secret: '',
      tokenEndpointAuthMethod: 'none',
      redirect_uris: ['http://127.0.0.1:55667/callback'],
      grants: ['authorization_code', 'refresh_token'],
      client_name: 'Token Route Test Client',
    };
    const grant = {
      projectId: 'proj_123',
      scopes: ['querying', 'schema'],
    };

    vi.mocked(model.getClient).mockResolvedValue(client as never);
    vi.mocked(model.getAuthorizationCode).mockResolvedValue({
      authorizationCode: 'code-123',
      client,
      user: { id: 'user-1', name: 'User', email: 'user@example.com' },
      expiresAt: new Date(Date.now() + 60_000),
      token: {
        access_token: 'upstream-access',
        refresh_token: 'upstream-refresh',
        access_token_expires_at: Date.now() + 3600_000,
      },
      scope: 'read write',
      grant,
    } as never);

    vi.mocked(model.saveToken).mockResolvedValue({
      accessToken: 'saved-access',
      refreshToken: 'saved-refresh',
      expires_at: Date.now() + 3600_000,
      scope: 'read write',
      client,
      user: { id: 'user-1' },
      grant,
    } as never);

    const body = new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: client.id,
      code: 'code-123',
      redirect_uri: client.redirect_uris[0],
    });
    const request = new NextRequest('http://localhost/api/token', {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: body.toString(),
    });

    const response = await POST(request);
    expect(response.status).toBe(200);

    expect(model.saveToken).toHaveBeenCalledWith(
      expect.objectContaining({
        grant,
      }),
    );
  });

  it('returns the authorization code scope including * on the token', async () => {
    const client = {
      id: 'client-123',
      secret: '',
      tokenEndpointAuthMethod: 'none',
      redirect_uris: ['http://127.0.0.1:55667/callback'],
      grants: ['authorization_code', 'refresh_token'],
      client_name: 'Token Route Test Client',
    };

    vi.mocked(model.getClient).mockResolvedValue(client as never);
    vi.mocked(model.getAuthorizationCode).mockResolvedValue({
      authorizationCode: 'code-123',
      client,
      user: { id: 'user-1', name: 'User', email: 'user@example.com' },
      expiresAt: new Date(Date.now() + 60_000),
      token: {
        access_token: 'upstream-access',
        refresh_token: 'upstream-refresh',
        access_token_expires_at: Date.now() + 3600_000,
      },
      scope: 'read write *',
      grant: { projectId: null, scopes: null },
    } as never);

    vi.mocked(model.saveToken).mockResolvedValue({
      accessToken: 'saved-access',
      refreshToken: 'saved-refresh',
      expires_at: Date.now() + 3600_000,
      scope: 'read write *',
      client,
      user: { id: 'user-1' },
    } as never);

    const body = new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: client.id,
      code: 'code-123',
      redirect_uri: client.redirect_uris[0],
    });
    const request = new NextRequest('http://localhost/api/token', {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: body.toString(),
    });

    const response = await POST(request);
    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual(
      expect.objectContaining({
        access_token: 'saved-access',
        token_type: 'bearer',
        refresh_token: 'saved-refresh',
        scope: 'read write *',
      }),
    );
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { NextRequest } from 'next/server';
import { GET, POST } from '../../app/api/authorize/route';
import { model } from '../oauth/model';
import { upstreamAuth } from '../../lib/oauth/client';

vi.mock('../oauth/model', () => ({
  model: {
    getClient: vi.fn(),
    getClientRegisterHeaders: vi.fn(),
    saveClientAuthContext: vi.fn(),
  },
}));

vi.mock('../../lib/oauth/client', () => ({
  upstreamAuth: vi.fn(async () => new URL('https://oauth.example/authorize')),
}));

const VALID_CLIENT = {
  id: 'client-123',
  client_name: 'Authorize Test Client',
  redirect_uris: ['http://127.0.0.1:55667/callback'],
  response_types: ['code'],
  grant_types: ['authorization_code', 'refresh_token'],
  tokenEndpointAuthMethod: 'none',
  secret: '',
};

function buildAuthorizeRequest(
  headers: Record<string, string> = {},
  scope = 'read write',
  extraParams: Record<string, string> = {},
): NextRequest {
  const params = new URLSearchParams({
    response_type: 'code',
    client_id: VALID_CLIENT.id,
    redirect_uri: VALID_CLIENT.redirect_uris[0],
    scope,
    state: 'test-state',
    ...extraParams,
  });

  return new NextRequest(
    `http://localhost/api/authorize?${params.toString()}`,
    {
      method: 'GET',
      headers,
    },
  );
}

function extractWriteCheckbox(html: string): string {
  const match = html.match(
    /<input[\s\S]*?name="scopes"[\s\S]*?value="write"[\s\S]*?class="scope-checkbox"[\s\S]*?\/>/,
  );
  expect(match).toBeTruthy();
  return match![0];
}

function extractEncodedState(html: string): string {
  const match = html.match(/<input type="hidden" name="state" value="([^"]+)"/);
  expect(match).toBeTruthy();
  return match![1];
}

function decodeState(html: string): Record<string, unknown> {
  return JSON.parse(atob(extractEncodedState(html)));
}

function decodeUpstreamAuthState(): Record<string, unknown> {
  const encoded = vi.mocked(upstreamAuth).mock.calls.at(-1)?.[0];
  if (typeof encoded !== 'string') {
    throw new Error('expected upstreamAuth to be called with encoded state');
  }
  return JSON.parse(atob(encoded)) as Record<string, unknown>;
}

function buildApproveRequest(
  requestedScopes: string[],
  selectedScopes: string[],
): NextRequest {
  const state = btoa(
    JSON.stringify({
      responseType: 'code',
      clientId: VALID_CLIENT.id,
      redirectUri: VALID_CLIENT.redirect_uris[0],
      scope: requestedScopes,
      state: 'test-state',
    }),
  );
  const form = new FormData();
  form.set('state', state);
  for (const scope of selectedScopes) {
    form.append('scopes', scope);
  }
  return new NextRequest('http://localhost/api/authorize', {
    method: 'POST',
    body: form,
  });
}

describe('/api/authorize route integration', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(model.getClient).mockResolvedValue(
      VALID_CLIENT as unknown as Awaited<ReturnType<typeof model.getClient>>,
    );
    vi.mocked(model.getClientRegisterHeaders).mockResolvedValue(undefined);
    vi.mocked(model.saveClientAuthContext).mockResolvedValue({
      grant: { projectId: null, scopes: null },
      scope: ['read', 'write'],
      readOnly: false,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    } as never);
  });

  it('defaults Full access to checked when no read-only header is set', async () => {
    const response = await GET(buildAuthorizeRequest());
    const html = await response.text();
    const writeCheckbox = extractWriteCheckbox(html);

    expect(response.status).toBe(200);
    expect(writeCheckbox).toContain('checked');
  });

  it('defaults Full access to unchecked when x-read-only is true', async () => {
    const response = await GET(
      buildAuthorizeRequest({
        'x-read-only': 'true',
      }),
    );
    const html = await response.text();
    const writeCheckbox = extractWriteCheckbox(html);

    expect(response.status).toBe(200);
    expect(writeCheckbox).not.toContain('checked');
  });

  it('defaults Full access to unchecked when readonly query param is true', async () => {
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', {
        readonly: 'true',
      }),
    );
    const html = await response.text();
    const writeCheckbox = extractWriteCheckbox(html);

    expect(response.status).toBe(200);
    expect(writeCheckbox).not.toContain('checked');
  });

  it('defaults Full access to unchecked when readonly=true is passed via resource query', async () => {
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', {
        resource: 'https://mcp.neon.tech/mcp?readonly=true',
      }),
    );
    const html = await response.text();
    const writeCheckbox = extractWriteCheckbox(html);

    expect(response.status).toBe(200);
    expect(writeCheckbox).not.toContain('checked');
  });

  it('defaults Full access to unchecked from saved register x-read-only header', async () => {
    vi.mocked(model.getClientRegisterHeaders).mockResolvedValue({
      headers: {
        'x-read-only': 'true',
      },
      createdAt: Date.now(),
    });

    const response = await GET(buildAuthorizeRequest());
    const html = await response.text();
    const writeCheckbox = extractWriteCheckbox(html);

    expect(response.status).toBe(200);
    expect(writeCheckbox).not.toContain('checked');
  });

  it('does not embed grant context in the upstream OAuth state parameter', async () => {
    const response = await GET(buildAuthorizeRequest());
    const html = await response.text();
    const state = decodeState(html);

    expect(response.status).toBe(200);
    expect(state).not.toHaveProperty('grant');
  });

  it('preserves resource parameter in encoded state for callback grant resolution', async () => {
    const resource =
      'https://mcp.neon.tech/mcp?projectId=proj-123&category=schema';
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', { resource }),
    );
    const html = await response.text();
    const state = decodeState(html);

    expect(response.status).toBe(200);
    expect(state).toHaveProperty('resource', resource);
  });

  it('persists parsed resource grant context in client auth context KV', async () => {
    const resource =
      'https://mcp.neon.tech/mcp?projectId=proj-123&category=querying,schema';
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', { resource }),
    );

    expect(response.status).toBe(200);
    expect(vi.mocked(model.saveClientAuthContext)).toHaveBeenCalledWith(
      VALID_CLIENT.id,
      expect.objectContaining({
        grant: {
          projectId: 'proj-123',
          scopes: ['querying', 'schema'],
        },
      }),
    );
  });

  it('returns invalid_target when resource parameter is malformed', async () => {
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', {
        resource: '/mcp?category=schema',
      }),
    );

    expect(response.status).toBe(400);
    await expect(response.json()).resolves.toEqual({
      error: 'invalid_target',
      error_description: 'Invalid resource parameter',
    });
  });

  it('returns invalid_target when resource parameter is not https', async () => {
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', {
        resource: 'http://mcp.neon.tech/mcp?category=schema',
      }),
    );

    expect(response.status).toBe(400);
    await expect(response.json()).resolves.toEqual({
      error: 'invalid_target',
      error_description: 'Invalid resource parameter',
    });
  });

  it('renders consent HTML on GET and does not redirect to upstream OAuth', async () => {
    const resource =
      'https://mcp.neon.tech/mcp?projectId=proj-123&category=querying';
    const response = await GET(
      buildAuthorizeRequest({}, 'read write', { resource }),
    );
    const html = await response.text();

    expect(response.status).toBe(200);
    expect(html).toContain('scope-checkbox');
    expect(upstreamAuth).not.toHaveBeenCalled();
  });

  it('keeps requested * on the granted scope when write is approved', async () => {
    const response = await GET(buildAuthorizeRequest({}, 'read write *'));
    const state = decodeState(await response.text());

    expect(response.status).toBe(200);
    expect(model.saveClientAuthContext).toHaveBeenCalledWith(
      VALID_CLIENT.id,
      expect.objectContaining({
        scope: ['read', 'write', '*'],
        readOnly: false,
      }),
    );
    expect(state.scope).toEqual(['read', 'write', '*']);
  });

  it('drops * when the request is read-only', async () => {
    const response = await GET(
      buildAuthorizeRequest({}, 'read write *', {
        readonly: 'true',
      }),
    );

    expect(response.status).toBe(200);
    expect(model.saveClientAuthContext).toHaveBeenCalledWith(
      VALID_CLIENT.id,
      expect.objectContaining({
        scope: ['read'],
        readOnly: true,
      }),
    );
  });

  it('keeps requested * on POST when Full access stays checked', async () => {
    const response = await POST(
      buildApproveRequest(['read', 'write', '*'], ['read', 'write']),
    );

    expect(response.status).toBe(307);
    expect(model.saveClientAuthContext).toHaveBeenCalledWith(
      VALID_CLIENT.id,
      expect.objectContaining({
        scope: ['read', 'write', '*'],
        readOnly: false,
      }),
    );
    expect(decodeUpstreamAuthState().scope).toEqual(['read', 'write', '*']);
  });

  it('does not issue * on POST when Full access is unchecked', async () => {
    const response = await POST(
      buildApproveRequest(['read', 'write', '*'], ['read']),
    );

    expect(response.status).toBe(307);
    expect(model.saveClientAuthContext).toHaveBeenCalledWith(
      VALID_CLIENT.id,
      expect.objectContaining({
        scope: ['read'],
        readOnly: true,
      }),
    );
    expect(decodeUpstreamAuthState().scope).toEqual(['read']);
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';

const {
  discoveryMock,
  buildAuthorizationUrlMock,
  authorizationCodeGrantMock,
  clientSecretPostMock,
  refreshTokenGrantMock,
} = vi.hoisted(() => ({
  discoveryMock: vi.fn(),
  buildAuthorizationUrlMock: vi.fn(),
  authorizationCodeGrantMock: vi.fn(),
  clientSecretPostMock: vi.fn(() => 'client-secret-post-auth'),
  refreshTokenGrantMock: vi.fn(),
}));

vi.mock('openid-client', () => ({
  discovery: discoveryMock,
  buildAuthorizationUrl: buildAuthorizationUrlMock,
  authorizationCodeGrant: authorizationCodeGrantMock,
  ClientSecretPost: clientSecretPostMock,
  refreshTokenGrant: refreshTokenGrantMock,
  // The real openid-client exports `customFetch` as a Symbol; tests
  // don't actually exercise the fetch path so any Symbol is fine.
  customFetch: Symbol('customFetch'),
}));

vi.mock('../../lib/config', () => ({
  CLIENT_ID: 'client-id',
  CLIENT_SECRET: 'client-secret',
  SERVER_HOST: 'https://mcp.neon.tech',
  UPSTREAM_OAUTH_HOST: 'https://oauth.neon.tech',
}));

describe('lib/oauth/client upstream OAuth request shape', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    discoveryMock.mockResolvedValue({ config: 'upstream-config' });
    buildAuthorizationUrlMock.mockReturnValue(
      new URL('https://oauth.neon.tech/authorize'),
    );
    authorizationCodeGrantMock.mockResolvedValue({
      access_token: 'token',
      expiresIn: () => 3600,
    });
  });

  it('does not include resource parameter in upstream authorization URL', async () => {
    const { upstreamAuth } = await import('../../lib/oauth/client');
    await upstreamAuth('encoded-state');

    expect(buildAuthorizationUrlMock).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({
        state: 'encoded-state',
      }),
    );
    expect(buildAuthorizationUrlMock).toHaveBeenCalledWith(
      expect.anything(),
      expect.not.objectContaining({
        resource: expect.anything(),
      }),
    );
  });

  it('does not include resource parameter in code exchange token request', async () => {
    const { exchangeCode } = await import('../../lib/oauth/client');
    const callbackUrl = new URL('https://mcp.neon.tech/callback?code=abc');

    await exchangeCode(callbackUrl, 'encoded-state');

    expect(authorizationCodeGrantMock).toHaveBeenCalledWith(
      expect.anything(),
      callbackUrl,
      {
        expectedState: 'encoded-state',
        idTokenExpected: true,
      },
    );
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { NextRequest } from 'next/server';
import { POST, OPTIONS } from '../../app/api/register/route';
import { model } from '../oauth/model';

vi.mock('../oauth/model', () => ({
  model: {
    saveClient: vi.fn(),
    saveClientRegisterHeaders: vi.fn(),
  },
}));

const VALID_PAYLOAD = {
  client_name: 'Codex',
  redirect_uris: ['http://127.0.0.1:55555/callback'],
  grant_types: ['authorization_code', 'refresh_token'],
  response_types: ['code'],
  token_endpoint_auth_method: 'none',
};

function buildRequest(
  body: unknown,
  headers: Record<string, string> = {},
): NextRequest {
  return new NextRequest('http://localhost/api/register', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...headers,
    },
    body: JSON.stringify(body),
  });
}

describe('/api/register route integration', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(model.saveClient).mockImplementation(async (client) => client);
    vi.mocked(model.saveClientRegisterHeaders).mockImplementation(
      async (_clientId, requestHeaders) => ({
        headers: requestHeaders,
        createdAt: Date.now(),
      }),
    );
  });

  it('returns a valid response and stores register headers for a valid request', async () => {
    const response = await POST(
      buildRequest(VALID_PAYLOAD, {
        'x-read-only': 'true',
      }),
    );
    const body = (await response.json()) as {
      client_id: string;
      client_secret: string;
      token_endpoint_auth_method: string;
    };

    expect(response).toBeInstanceOf(Response);
    expect(response.status).toBe(200);
    expect(body.client_id).toBeTypeOf('string');
    expect(body.client_secret).toBeTypeOf('string');
    expect(body.token_endpoint_auth_method).toBe('none');
    expect(vi.mocked(model.saveClient)).toHaveBeenCalledOnce();
    expect(vi.mocked(model.saveClientRegisterHeaders)).toHaveBeenCalledWith(
      body.client_id,
      expect.objectContaining({
        'x-read-only': 'true',
      }),
    );
  });

  it('returns 400 when client_name is missing', async () => {
    const { client_name, ...payloadWithoutClientName } = VALID_PAYLOAD;
    void client_name;

    const response = await POST(buildRequest(payloadWithoutClientName));
    const body = (await response.json()) as {
      error: string;
      error_description: string;
    };

    expect(response.status).toBe(400);
    expect(body.error).toBe('invalid_request');
    expect(body.error_description).toContain('client_name');
    expect(vi.mocked(model.saveClient)).not.toHaveBeenCalled();
  });

  it('returns 400 when redirect_uris is missing', async () => {
    const { redirect_uris, ...payloadWithoutRedirectUris } = VALID_PAYLOAD;
    void redirect_uris;

    const response = await POST(buildRequest(payloadWithoutRedirectUris));
    const body = (await response.json()) as {
      error: string;
      error_description: string;
    };

    expect(response.status).toBe(400);
    expect(body.error).toBe('invalid_request');
    expect(body.error_description).toContain('redirect_uris');
    expect(vi.mocked(model.saveClient)).not.toHaveBeenCalled();
  });

  it('returns 400 when grant_types contains unsupported values', async () => {
    const response = await POST(
      buildRequest({
        ...VALID_PAYLOAD,
        grant_types: ['client_credentials'],
      }),
    );
    const body = (await response.json()) as {
      error: string;
      error_description: string;
    };

    expect(response.status).toBe(400);
    expect(body.error).toBe('invalid_request');
    expect(body.error_description).toContain('grant_types');
    expect(vi.mocked(model.saveClient)).not.toHaveBeenCalled();
  });

  it('returns 400 when response_types contains unsupported values', async () => {
    const response = await POST(
      buildRequest({
        ...VALID_PAYLOAD,
        response_types: ['token'],
      }),
    );
    const body = (await response.json()) as {
      error: string;
      error_description: string;
    };

    expect(response.status).toBe(400);
    expect(body.error).toBe('invalid_request');
    expect(body.error_description).toContain('response_types');
    expect(vi.mocked(model.saveClient)).not.toHaveBeenCalled();
  });

  it('returns 204 and CORS headers for OPTIONS', async () => {
    const response = await OPTIONS();

    expect(response).toBeInstanceOf(Response);
    expect(response.status).toBe(204);
    expect(response.headers.get('access-control-allow-origin')).toBe('*');
    expect(response.headers.get('access-control-allow-methods')).toContain(
      'POST',
    );
    expect(response.headers.get('access-control-allow-headers')).toContain(
      'x-read-only',
    );
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { NextRequest } from 'next/server';
import { GET } from '../../app/callback/route';
import { model } from '../oauth/model';
import { exchangeCode } from '../../lib/oauth/client';
import { resolveAccountFromAuth } from '../server/account';
import { logger } from '../utils/logger';

vi.mock('../oauth/model', () => ({
  model: {
    getClient: vi.fn(),
    getClientAuthContext: vi.fn(),
    deleteClientAuthContext: vi.fn(),
    saveAuthorizationCode: vi.fn(),
  },
}));

vi.mock('../../lib/oauth/client', () => ({
  exchangeCode: vi.fn(),
}));

vi.mock('../oauth/utils', () => ({
  generateRandomString: vi.fn(() => 'fixed-random'),
}));

vi.mock('../server/api', () => ({
  createNeonClient: vi.fn(() => ({
    getAuthDetails: vi.fn(async () => ({ data: { auth_method: 'session' } })),
  })),
}));

vi.mock('../server/account', () => ({
  resolveAccountFromAuth: vi.fn(),
}));

function buildState(overrides: Partial<Record<string, unknown>> = {}): string {
  return btoa(
    JSON.stringify({
      responseType: 'code',
      clientId: 'client-123',
      redirectUri: 'http://127.0.0.1:55667/callback',
      scope: ['read', 'write'],
      state: 'client-state',
      ...overrides,
    }),
  );
}

function buildRequest(state: string): NextRequest {
  const url = `http://localhost/callback?code=upstream-code&state=${encodeURIComponent(state)}`;
  return new NextRequest(url, { method: 'GET' });
}

describe('/callback route integration', () => {
  beforeEach(() => {
    vi.clearAllMocks();

    vi.mocked(model.getClient).mockResolvedValue({
      id: 'client-123',
      client_name: 'Callback Test Client',
      redirect_uris: ['http://127.0.0.1:55667/callback'],
    } as never);

    vi.mocked(exchangeCode).mockResolvedValue({
      access_token: 'upstream-access',
      refresh_token: 'upstream-refresh',
      id_token: 'upstream-id-token',
      expiresIn: () => 3600,
    } as never);

    vi.mocked(resolveAccountFromAuth).mockResolvedValue({
      id: 'user-1',
      name: 'User',
      email: 'user@example.com',
      isOrg: false,
    } as never);
    vi.mocked(model.getClientAuthContext).mockResolvedValue({
      grant: { projectId: null, scopes: null },
      scope: ['read', 'write'],
      readOnly: false,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    } as never);
    vi.mocked(model.deleteClientAuthContext).mockResolvedValue(true);
  });

  it('uses persisted grant from KV and scope from authorize state', async () => {
    const resource =
      'https://mcp.neon.tech/mcp?projectId=proj-123&category=querying,schema';
    const state = buildState({ resource });
    vi.mocked(model.getClientAuthContext).mockResolvedValue({
      grant: { projectId: 'proj-123', scopes: ['querying', 'schema'] },
      scope: ['read'],
      readOnly: true,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    } as never);

    const response = await GET(buildRequest(state));

    expect(response.status).toBe(307);
    expect(exchangeCode).toHaveBeenCalledWith(expect.any(URL), state);
    expect(model.saveAuthorizationCode).toHaveBeenCalledWith(
      expect.objectContaining({
        scope: 'read write',
        grant: {
          projectId: 'proj-123',
          scopes: ['querying', 'schema'],
        },
      }),
    );
  });

  it('prefers authorize-state scope over a different client-keyed KV scope', async () => {
    const state = buildState({ scope: ['read', 'write', '*'] });
    vi.mocked(model.getClientAuthContext).mockResolvedValue({
