import { NeonDbError, neon } from '@neondatabase/serverless';
import { startSpan } from '@sentry/node';
import {
  INSPECT_DEFAULT_LIMIT,
  INSPECT_QUERIES,
  type InspectCheck,
} from '../../inspect/queries';
import {
  assembleInspectReport,
  type InspectDatabaseBatch,
  type InspectDatabaseResult,
} from '../../inspect/report';
import {
  formatInspectQueryError,
  selectInspectTargets,
} from '../../inspect/targets';
import { Api } from '../../neon-client';
import { NotFoundError } from '../../server/errors';
import { ToolHandlerExtraParams } from '../types';
import { handleGetConnectionString } from './connection-string';
import { getDefaultBranch, getOnlyProject } from './utils';

type InspectDatabaseParams = {
  check: InspectCheck;
  projectId?: string;
  branchId?: string;
  databaseName?: string;
  computeId?: string;
  limit?: number;
};

/**
 * A failed diagnostic is a bug in this catalog, not in a caller's SQL, so it must
 * not be classified as a client error the way a failed `run_sql` is.
 * `handleToolError` returns `NeonDbError` straight to the caller without logging
 * it or reporting it to Sentry; rethrowing keeps the actionable message and gets
 * the failure recorded.
 */
async function runDiagnostic<T>(
  check: InspectCheck,
  run: () => Promise<T>,
): Promise<T> {
  try {
    return await run();
  } catch (error) {
    if (error instanceof NeonDbError) {
      throw new Error(
        `The "${check}" diagnostic failed against Postgres: ${error.message}`,
        { cause: error },
      );
    }
    throw error;
  }
}

async function runInspectOnDatabase(
  check: InspectCheck,
  uri: string,
  databaseName: string,
): Promise<Record<string, unknown>[]> {
  const query = INSPECT_QUERIES[check];
  const sql = neon(uri);

  if (query.requiresExtension) {
    const installed = await runDiagnostic(check, () =>
      sql.query('SELECT 1 FROM pg_extension WHERE extname = $1', [
        query.requiresExtension,
      ]),
    );
    if (installed.length === 0) {
      throw new NotFoundError(
        `The "${check}" check needs the "${query.requiresExtension}" extension, which is not installed on database "${databaseName}". Installing it writes to the user's database, so ask the user first, then run \`CREATE EXTENSION IF NOT EXISTS ${query.requiresExtension};\` with run_sql.`,
      );
    }
  }

  const [rows] = await runDiagnostic(check, () =>
    sql.transaction([sql.query(query.sql)], { readOnly: true }),
  );
  return rows;
}

function rethrowInspectError(
  error: unknown,
  wrapped: string | undefined,
): never {
  if (wrapped === undefined) {
    throw error instanceof Error ? error : new Error(String(error));
  }
  if (error instanceof NotFoundError) {
    throw new NotFoundError(wrapped);
  }
  throw new Error(wrapped, {
    cause: error instanceof Error ? error : undefined,
  });
}

/**
 * Every check runs in a `READ ONLY` transaction, so read-only mode does not
 * require a read-only replica.
 */
export async function handleInspectDatabase(
  {
    check,
    projectId,
    branchId,
    databaseName,
    computeId,
    limit = INSPECT_DEFAULT_LIMIT,
  }: InspectDatabaseParams,
  neonClient: Api<unknown>,
  extra: ToolHandlerExtraParams,
): Promise<InspectDatabaseResult> {
  return await startSpan({ name: 'inspect_database' }, async () => {
    const query = INSPECT_QUERIES[check];

    if (!projectId) {
      const project = await getOnlyProject(neonClient, extra);
      projectId = project.id;
    }
    if (!branchId) {
      const defaultBranch = await getDefaultBranch(projectId, neonClient);
      branchId = defaultBranch.id;
    }

    let branchDatabaseCount = 1;
    let selection;
    if (databaseName !== undefined) {
      selection = selectInspectTargets({
        databaseName,
        branchDatabases: [],
        scope: query.scope,
      });
    } else {
      const { data } = await neonClient.listProjectBranchDatabases(
        projectId,
        branchId,
      );
      const branchDatabases = data.databases.map((database) => database.name);
      if (branchDatabases.length === 0) {
        throw new NotFoundError('No databases found in your project branch');
      }
      branchDatabaseCount = branchDatabases.length;
      selection = selectInspectTargets({
        branchDatabases,
        scope: query.scope,
      });
    }

    const batches: InspectDatabaseBatch[] = [];
    for (const name of selection.databases) {
      try {
        const connection = await handleGetConnectionString(
          { projectId, branchId, databaseName: name, computeId },
          neonClient,
          extra,
        );
        batches.push({
          database: name,
          rows: await runInspectOnDatabase(check, connection.uri, name),
        });
      } catch (error) {
        const reason = error instanceof Error ? error.message : String(error);
        rethrowInspectError(
          error,
          formatInspectQueryError({
            reason,
            database: name,
            databaseName,
            offerDatabaseNameHint: branchDatabaseCount > 1,
            scope: query.scope,
            requiresExtension: query.requiresExtension,
          }),
        );
      }
    }

    return assembleInspectReport({
      check,
      query,
      projectId,
      branchId,
      batches,
      includeDatabaseColumn: selection.includeDatabaseColumn,
      includeDatabaseName: databaseName !== undefined,
      limit,
    });
  });
}

import { describe, expect, it, vi } from 'vitest';
import {
  isPgConnectFailure,
  shouldReinitKeyv,
  withPgConnectRetry,
} from '../oauth/kv-store';

// These pin the predicate / retry helper contract that the /callback
// hot-path depends on. Regression for the 2026-05-12 OAUTH_DATABASE_URL
// compute scale-from-zero hiccup where `internal_error` failures were both
// undebuggable (no clientId in SLO) and unmasked (no retry against the
// freshly-woken compute).

describe('isPgConnectFailure', () => {
  it('matches Postgres XX000 by code', () => {
    const err = Object.assign(new Error("Couldn't connect to compute node"), {
      code: 'XX000',
    });
    expect(isPgConnectFailure(err)).toBe(true);
  });

  it('matches existing connect-failure patterns via shouldReinitKeyv', () => {
    // Sanity-check that we still catch the patterns we already covered.
    expect(isPgConnectFailure(new Error('ECONNRESET'))).toBe(true);
    expect(isPgConnectFailure(new Error('ETIMEDOUT'))).toBe(true);
    expect(
      isPgConnectFailure(new Error('password authentication failed')),
    ).toBe(true);
    expect(shouldReinitKeyv(new Error('ETIMEDOUT'))).toBe(true);
  });

  it('does NOT match unrelated errors', () => {
    expect(isPgConnectFailure(new Error('not a pg error'))).toBe(false);
    expect(
      isPgConnectFailure(
        Object.assign(new Error('check failed'), { code: '23505' }),
      ),
    ).toBe(false);
    expect(isPgConnectFailure(undefined)).toBe(false);
    expect(isPgConnectFailure(null)).toBe(false);
    expect(isPgConnectFailure('string error')).toBe(false);
  });
});

describe('withPgConnectRetry', () => {
  it('returns the value on first success without retrying', async () => {
    const fn = vi.fn(async () => 'ok');
    await expect(withPgConnectRetry('test.op', fn)).resolves.toBe('ok');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('retries once on XX000 and succeeds on the second attempt', async () => {
    const xx000 = Object.assign(new Error("Couldn't connect"), {
      code: 'XX000',
    });
    const fn = vi
      .fn<() => Promise<string>>()
      .mockRejectedValueOnce(xx000)
      .mockResolvedValue('ok');
    await expect(withPgConnectRetry('test.op', fn)).resolves.toBe('ok');
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it('throws after exhausting both attempts on persistent XX000', async () => {
    const xx000 = Object.assign(new Error("Couldn't connect"), {
      code: 'XX000',
    });
    const fn = vi.fn(async () => {
      throw xx000;
    });
    await expect(withPgConnectRetry('test.op', fn)).rejects.toBe(xx000);
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it('does NOT retry non-retryable errors', async () => {
    const err = new Error('logic bug');
    const fn = vi.fn(async () => {
      throw err;
    });
    await expect(withPgConnectRetry('test.op', fn)).rejects.toBe(err);
    expect(fn).toHaveBeenCalledTimes(1);
  });
});

import { describe, it, expect, vi } from 'vitest';

vi.mock('../utils/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));

import { retryAsync } from '../utils/retry';

describe('retryAsync', () => {
  it('returns immediately on first-attempt success', async () => {
    const fn = vi.fn().mockResolvedValue('ok');
    const result = await retryAsync(fn, {
      attempts: 3,
      delaysMs: [10, 20],
      op: 'test',
    });
    expect(result).toBe('ok');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('retries on failure and returns on later success', async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error('fail-1'))
      .mockRejectedValueOnce(new Error('fail-2'))
      .mockResolvedValue('ok');
    const result = await retryAsync(fn, {
      attempts: 3,
      delaysMs: [1, 1],
      op: 'test',
    });
    expect(result).toBe('ok');
    expect(fn).toHaveBeenCalledTimes(3);
  });

  it('throws the last error after exhausting all attempts', async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error('fail-1'))
      .mockRejectedValueOnce(new Error('fail-2'))
      .mockRejectedValue(new Error('fail-3'));
    await expect(
      retryAsync(fn, { attempts: 3, delaysMs: [1, 1], op: 'test' }),
    ).rejects.toThrow('fail-3');
    expect(fn).toHaveBeenCalledTimes(3);
  });

  it('throws on misconfigured delaysMs length (attempts - 1 required)', async () => {
    await expect(
      retryAsync(vi.fn(), { attempts: 3, delaysMs: [1, 2, 3], op: 'test' }),
    ).rejects.toThrow(/misconfigured/);
    await expect(
      retryAsync(vi.fn(), { attempts: 3, delaysMs: [1], op: 'test' }),
    ).rejects.toThrow(/misconfigured/);
  });

  it('does not delay after the final attempt fails', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('always fails'));
    const start = Date.now();
    await expect(
      retryAsync(fn, { attempts: 2, delaysMs: [50], op: 'test' }),
    ).rejects.toThrow('always fails');
    const elapsed = Date.now() - start;
    // Two attempts with one 50ms delay between them. Total should be
    // ~50ms + small overhead. Crucially, NO trailing delay.
    expect(elapsed).toBeLessThan(150);
    expect(fn).toHaveBeenCalledTimes(2);
  });

  describe('shouldRetry predicate', () => {
    it('does not retry when predicate returns false', async () => {
      const fn = vi
        .fn()
        .mockRejectedValueOnce(new Error('non-retryable'))
        .mockResolvedValue('would-have-succeeded');
      await expect(
        retryAsync(fn, {
          attempts: 3,
          delaysMs: [1, 1],
          op: 'test',
          shouldRetry: () => false,
        }),
      ).rejects.toThrow('non-retryable');
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('retries only when predicate returns true', async () => {
      const fn = vi
        .fn()
        .mockRejectedValueOnce(new Error('retryable'))
        .mockResolvedValue('ok');
      const result = await retryAsync(fn, {
        attempts: 3,
        delaysMs: [1, 1],
        op: 'test',
        shouldRetry: (err) =>
          err instanceof Error && err.message === 'retryable',
      });
      expect(result).toBe('ok');
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('mid-stream non-retryable error stops the loop immediately', async () => {
      const fn = vi
        .fn()
        .mockRejectedValueOnce(new Error('retry me'))
        .mockRejectedValueOnce(new Error('do NOT retry me'))
        .mockResolvedValue('never reached');
      await expect(
        retryAsync(fn, {
          attempts: 5,
          delaysMs: [1, 1, 1, 1],
          op: 'test',
          shouldRetry: (err) =>
            err instanceof Error && err.message === 'retry me',
        }),
      ).rejects.toThrow('do NOT retry me');
      expect(fn).toHaveBeenCalledTimes(2);
    });
  });
});

name: Deploy to Preview

on:
  pull_request:
    types: [labeled, synchronize, closed]

jobs:
  deploy:
    # Deploy when: (1) the deploy-preview label is added, OR (2) a new commit is pushed to a PR that already has the label
    if: |
      (github.event.action == 'labeled' && github.event.label.name == 'deploy-preview') ||
      (github.event.action == 'synchronize' && contains(github.event.pull_request.labels.*.name, 'deploy-preview'))
    runs-on:
      group: neondatabase-protected-runner-group
      labels: linux-ubuntu-latest
    permissions:
      contents: write
      pull-requests: write
      deployments: write
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
        with:
          fetch-depth: 1
          ref: ${{ github.event.pull_request.head.sha }}

      # Only remove labels from other PRs when a new label is added (not on every commit)
      - name: Remove deploy-preview label from other PRs
        if: github.event.action == 'labeled'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const currentPR = context.payload.pull_request.number;

            // Find all open PRs with the 'deploy-preview' label
            const { data: prs } = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              labels: 'deploy-preview',
              state: 'open'
            });

            // Remove label from other PRs
            for (const pr of prs) {
              if (pr.number !== currentPR) {
                console.log(`Removing 'deploy-preview' label from PR #${pr.number}`);
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr.number,
                  name: 'deploy-preview'
                });

                // Notify the other PR
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr.number,
                  body: `⚠️ The \`deploy-preview\` label was removed because PR #${currentPR} now owns the preview environment.`
                });
              }
            }

      - name: Push to preview branch
        run: |
          git push origin HEAD:refs/heads/preview --force

      # Creates a GitHub Deployment record to track this deployment in the GitHub UI.
      # Note: This doesn't perform the actual deployment - that happens when Vercel
      # detects the push to the preview branch above. This step just creates a visible
      # record in GitHub's "Environments" tab and adds the deployment link to the PR.
      - name: Create GitHub Deployment
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const deployment = await github.rest.repos.createDeployment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: context.payload.pull_request.head.sha,
              environment: 'preview',
              auto_merge: false,
              required_contexts: [],
              description: `PR #${context.payload.pull_request.number}: ${context.payload.pull_request.title}`
            });

            await github.rest.repos.createDeploymentStatus({
              owner: context.repo.owner,
              repo: context.repo.repo,
              deployment_id: deployment.data.id,
              state: 'success',
              environment_url: 'https://preview-mcp.neon.tech',
              description: 'Deployment successful'
            });

      # Only comment on initial label, not on every commit push
      - name: Comment on PR
        if: github.event.action == 'labeled'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: '🚀 Deployed to https://preview-mcp.neon.tech\n\nThis PR now owns the preview environment. OAuth flow is available for testing.'
            })

  # Automatically remove the deploy-preview label when a PR is merged or closed
  cleanup:
    if: github.event.action == 'closed' && contains(github.event.pull_request.labels.*.name, 'deploy-preview')
    runs-on:
      group: neondatabase-protected-runner-group
      labels: linux-ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Remove deploy-preview label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const prNumber = context.payload.pull_request.number;
            const merged = context.payload.pull_request.merged;

            console.log(`PR #${prNumber} was ${merged ? 'merged' : 'closed'}. Removing 'deploy-preview' label.`);

            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: 'deploy-preview'
              });
            } catch (error) {
              // Label might already be removed
              console.log('Label already removed or not found:', error.message);
            }

import { AuthInfo } from '@modelcontextprotocol/sdk/server/auth/types.js';
import type { AuthDetailsResponse } from '../neon-client';

export type AuthMethod = AuthDetailsResponse['auth_method'];

export type AuthContext = {
  extra: {
    readOnly?: boolean;
    authMethod: AuthMethod;
    account: {
      id: string;
      name: string;
      email?: string;
      isOrg?: boolean; // For STDIO mode with org API key
    };
    client?: {
      id: string;
      name: string;
    };
    [key: string]: unknown;
  };
} & AuthInfo;

import crypto from 'crypto';

export const generateRandomString = (length: number): string => {
  const charset =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const array = new Uint8Array(length);
  crypto.getRandomValues(array);
  return Array.from(array, (byte) => charset[byte % charset.length]).join('');
};

export const verifyPKCE = (
  codeChallenge: string,
  codeChallengeMethod: string,
  codeVerifier: string,
): boolean => {
  if (!codeChallenge || !codeChallengeMethod || !codeVerifier) {
    return false;
  }

  if (codeChallengeMethod === 'S256') {
    const hash = crypto
      .createHash('sha256')
      .update(codeVerifier)
      .digest('base64url');
    return codeChallenge === hash;
  }

  if (codeChallengeMethod === 'plain') {
    return codeChallenge === codeVerifier;
  }

  return false;
};

/**
 * Cross-instance distributed lock for refresh-token rotation.
 *
 * The cliff we're closing: two Vercel instances each receive a /api/token
 * request with the same refresh_token RT₁ within milliseconds, both forward
 * to upstream Hydra, and Hydra's reuse detector revokes the entire chain on
 * the second arrival. Same-instance races are already absorbed by the
 * in-memory `singleflight`; this module extends the same dedup property
 * across instances using Upstash Redis.
 *
 * Pattern: SET NX PX <ttl> with a random owner token; release is gated by
 * Lua to avoid cross-instance lock-stealing after a TTL expiry. Lock-acquire
 * failures fall through to the underlying executor — preserves the
 * pre-lock behaviour if Redis is unavailable, so the only failure mode is
 * "we don't get the cross-instance dedup benefit," not "refresh breaks."
 */

import { randomUUID } from 'node:crypto';
import { createClient, type RedisClientType } from 'redis';
import { logger } from '../utils/logger';

const LOCK_KEY_PREFIX = 'mcp:refresh-lock:';
// Short TTL so a vanished holder (Vercel function killed mid-flight by
// the platform — OOM, container shutdown, host eviction) doesn't keep
// waiters blocked for the previous 30s. The holder extends the TTL via a
// heartbeat while it's still alive (see `runWithHeartbeat`), so legitimate
// slow upstream calls don't get yanked. Sized at 2× HEARTBEAT_MS so one
// missed heartbeat (Redis blip, event-loop stall) doesn't expire the lock.
const LOCK_TTL_MS = 6_000;
const LOCK_HEARTBEAT_MS = 2_500;
const LOCK_POLL_INTERVAL_MS = 100;
// ~8s total waiter budget. Sized to cover the holder's upstream-call cap
// (UPSTREAM_REFRESH_TIMEOUT_MS in app/api/token/route.ts, ~4.5s) plus the
// holder's lock-release + transient-marker write, plus a margin for the
// waiter's own ~100ms poll granularity and Redis RTT. With this budget the
// holder's atomic Lua release + transient marker always lands first; the
// failure cache / marker then short-circuits the wait.
const LOCK_POLL_MAX_ATTEMPTS = 80;
// Cap total time a single waiter spends cycling through poll → takeover →
// poll. Prevents a takeover that itself vanishes from feeding the next
// waiter into another full poll loop.
const WAITER_TOTAL_BUDGET_MS = 8_000;
const REDIS_OP_TIMEOUT_MS = 500;

const TRANSIENT_KEY_PREFIX = 'mcp:refresh-transient:';
// Short — these are upstream 5xx-class errors that may recover. Long enough
// to absorb a wave of waiters, short enough that the next legitimate refresh
// attempt isn't masked.
const TRANSIENT_TTL_MS = 30_000;

let clientPromise: Promise<RedisClientType> | null = null;

function withTimeout<T>(promise: Promise<T>, op: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(`refresh-lock ${op} timed out`));
    }, REDIS_OP_TIMEOUT_MS);
    timer.unref?.();
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (err) => {
        clearTimeout(timer);
        reject(err);
      },
    );
  });
}

function getRedis(): Promise<RedisClientType> {
  if (clientPromise) return clientPromise;
  const url = process.env.KV_URL || process.env.REDIS_URL;
  if (!url) {
    return Promise.reject(
      new Error('KV_URL/REDIS_URL not set; refresh lock unavailable'),
    );
  }
  const client = createClient({ url }) as RedisClientType;
  client.on('error', (err) => {
    logger.error('refresh-lock redis error', { err });
    clientPromise = null;
  });
  const pending = client.connect().then(() => client);
  pending.catch(() => {
    clientPromise = null;
  });
  clientPromise = pending;
  return clientPromise;
}

function lockKey(refreshToken: string): string {
  return `${LOCK_KEY_PREFIX}${refreshToken}`;
}

function transientKey(refreshToken: string): string {
  return `${TRANSIENT_KEY_PREFIX}${refreshToken}`;
}

/**
 * Signal that the lock holder hit a transient (5xx-class) failure during the
 * upstream call. Concurrent waiters poll this marker and exit early instead
 * of waiting up to LOCK_POLL_MAX_ATTEMPTS × LOCK_POLL_INTERVAL_MS ≈ 5s and
 * surfacing as 503 lock-timeout. Best-effort; failure to write is tolerable
 * because the worst-case is just the existing lock-wait timeout path.
 */
export async function signalTransientFailure(
  refreshToken: string,
): Promise<void> {
  try {
    const redis = await getRedis();
    await withTimeout(
      redis.set(transientKey(refreshToken), '1', { PX: TRANSIENT_TTL_MS }),
      'set-transient',
    );
  } catch (err) {
    logger.warn('refresh-lock failed to signal transient failure', {
      err: err instanceof Error ? err.message : err,
    });
  }
}

/**
 * Check whether the lock holder recently signalled a transient failure for
 * this refresh token. Returns false on any Redis error so callers default
 * to the normal poll loop instead of erroring out.
 */
export async function peekTransientFailure(
  refreshToken: string,
): Promise<boolean> {
  try {
    const redis = await getRedis();
    const v = await withTimeout(
      redis.get(transientKey(refreshToken)),
      'get-transient',
    );
    return v !== null;
  } catch {
    return false;
  }
}

/** Atomic compare-and-delete so a slow holder can't release a TTL-replaced lock. */
const RELEASE_LUA = `
if redis.call("get", KEYS[1]) == ARGV[1] then
  return redis.call("del", KEYS[1])
else
  return 0
end
`;

/**
 * Atomic compare-and-delete + transient-marker write. Used when the holder
 * exits via an upstream-5xx-class error: setting the marker and releasing the
 * lock in a single Redis round-trip closes the race where a waiter sees the
 * lock as released but the marker hasn't propagated yet (and falls through to
 * a `transient_lock_timeout` instead of bailing fast as `transient_upstream_5xx`).
 *
 * Production observation: during a Hydra 5xx burst at 2026-05-08 07:17 UTC,
 * 12/12 lock waiters hit their poll timeout despite the holder calling
 * `signalTransientFailure` before throwing. Two non-atomic SETs on Upstash HA
 * Redis can land on different replicas, so the waiter's `redis.get(lockKey)`
 * sees the release before its `redis.get(transientKey)` sees the marker.
 */
const RELEASE_WITH_TRANSIENT_LUA = `
if redis.call("get", KEYS[1]) == ARGV[1] then
  redis.call("set", KEYS[2], ARGV[2], "PX", ARGV[3])
  return redis.call("del", KEYS[1])
else
  return 0
end
`;

/**
 * Atomic compare-and-extend (PEXPIRE only if owner matches). The heartbeat
 * uses this to extend the lock's TTL while the holder is alive, so a short
 * LOCK_TTL_MS doesn't yank legitimate slow upstream calls. If we no longer
 * own the lock (an extreme stall let it TTL-expire to a peer), we don't
 * extend it — the new owner is in charge.
 */
const HEARTBEAT_LUA = `
if redis.call("get", KEYS[1]) == ARGV[1] then
  return redis.call("pexpire", KEYS[1], ARGV[2])
else
  return 0
end
`;

const sleep = (ms: number) =>
  new Promise<void>((r) => {
    const t = setTimeout(r, ms);
    t.unref?.();
  });

/**
 * Runs `execute` while keeping the lock TTL refreshed via a heartbeat, then
 * releases the lock atomically — using either the plain release script or
 * the release-with-transient-marker script depending on the hint.
 *
 * Heartbeat failures are non-fatal (logged). Two consecutive missed
 * heartbeats let the lock TTL out — the cost is one extra waiter promotion,
 * not a cliff (the takeover path in `withRefreshLock` handles this).
 */
async function runWithHeartbeat<T>(
  redis: RedisClientType,
  refreshToken: string,
  owner: string,
  hint: ReleaseHint,
  execute: () => Promise<T>,
): Promise<T> {
  const lkey = lockKey(refreshToken);
  let timer: ReturnType<typeof setInterval> | undefined = setInterval(() => {
    // Fire-and-forget; failure means we missed a heartbeat.
    withTimeout(
      redis.eval(HEARTBEAT_LUA, {
        keys: [lkey],
        arguments: [owner, String(LOCK_TTL_MS)],
      }),
      'heartbeat',
    ).catch((err) => {
      logger.warn('refresh-lock heartbeat failed', {
        err: err instanceof Error ? err.message : err,
      });
    });
  }, LOCK_HEARTBEAT_MS);
  timer.unref?.();
  try {
    return await execute();
  } finally {
    if (timer) {
      clearInterval(timer);
      timer = undefined;
    }
    try {
      if (hint.markTransientForWaiters) {
        await withTimeout(
          redis.eval(RELEASE_WITH_TRANSIENT_LUA, {
            keys: [lkey, transientKey(refreshToken)],
            arguments: [owner, '1', String(TRANSIENT_TTL_MS)],
          }),
          'release-with-transient',
        );
      } else {
        await withTimeout(
          redis.eval(RELEASE_LUA, { keys: [lkey], arguments: [owner] }),
          'release',
        );
      }
    } catch (err) {
      // Lock will TTL out fast (LOCK_TTL_MS); failing release is non-fatal.
      logger.warn('refresh-lock release failed', {
        err: err instanceof Error ? err.message : err,
        markTransient: hint.markTransientForWaiters === true,
      });
    }
  }
}

/**
 * Run `execute` while holding a cross-instance lock on `refreshToken`. Other
 * instances calling concurrently with the same token will block on
 * `peekResult` until the holder either finishes (cache hit) or releases
 * (timeout / error fallthrough).
 *
 * - If we acquire the lock, we re-check `peekResult` once before running
 *   `execute` (a peer may have just finished and released).
 * - If we fail to acquire, we poll `peekResult` and the lock state for ~5s.
 *   On a cache hit we return it; on the lock disappearing we throw a
 *   503-class error so the client retries (the failure cache will absorb
 *   any retry storm).
 * - If Redis is unreachable, we log and run `execute` directly — we lose
 *   the cross-instance dedup but don't regress existing behavior.
 *
 * `peekResult` MUST be cheap and idempotent (it's called multiple times
 * during the wait loop).
 */
/**
 * Hint object passed to `execute` so the holder can request that the lock
 * release also writes the transient-failure marker atomically. Set
 * `markTransientForWaiters = true` when an upstream 5xx-class error is about
 * to throw — this is the race-free replacement for calling
 * `signalTransientFailure` separately.
 */
export type ReleaseHint = {
  markTransientForWaiters?: boolean;
};

export async function withRefreshLock<T>(
  refreshToken: string,
  execute: (hint: ReleaseHint) => Promise<T>,
  peekResult: () => Promise<T | undefined>,
): Promise<T> {
  let redis: RedisClientType;
  try {
    redis = await getRedis();
  } catch (err) {
    logger.warn('refresh-lock unavailable, falling back to direct execute', {
      err: err instanceof Error ? err.message : err,
    });
    // Fallback path: no lock, no waiters to signal. Hint discarded.
    return execute({});
  }

  const key = lockKey(refreshToken);
  const deadline = Date.now() + WAITER_TOTAL_BUDGET_MS;
  // Try to acquire the lock; if held, poll. On the first poll iteration where
  // we see the lock disappear without a cached result, attempt a takeover
  // (single retry — don't infinite-loop if the lock keeps getting grabbed-
  // and-vanished). Caps upstream calls at N+1 where N = number of vanished
  // holders observed, in practice always 1.
  let takeoverAttempted = false;

  while (Date.now() < deadline) {
    let acquired: string | null;
    const owner = randomUUID();
    try {
      acquired = await withTimeout(
        redis.set(key, owner, { NX: true, PX: LOCK_TTL_MS }),
        'set',
      );
    } catch (err) {
      logger.warn(
        'refresh-lock acquire failed, falling back to direct execute',
        { err: err instanceof Error ? err.message : err },
      );
      return execute({});
    }

    if (acquired === 'OK') {
      // A peer may have just released after writing the cache and before our
      // SET landed. Cheap to check; saves an upstream call when it hits.
      const fast = await peekResult();
      if (fast !== undefined) {
        // Best-effort release; we own a fresh lock no one is waiting on.
        try {
          await withTimeout(
            redis.eval(RELEASE_LUA, { keys: [key], arguments: [owner] }),
            'release',
          );
        } catch {
          /* TTLs out fast */
        }
        return fast;
      }
      if (takeoverAttempted) {
        // Useful in log aggregation: how often does the vanished-holder
        // pattern actually fire?
        logger.info('refresh-lock waiter took over after holder vanished');
      }
      const hint: ReleaseHint = {};
      // runWithHeartbeat keeps the short LOCK_TTL alive while execute runs,
      // and on completion releases via the appropriate Lua based on hint.
      return await runWithHeartbeat(redis, refreshToken, owner, hint, () =>
        execute(hint),
      );
    }

    // Another instance holds the lock. Poll for the result to materialize
    // or for the lock to disappear (signalling holder death).
    let lockDisappeared = false;
    for (let i = 0; i < LOCK_POLL_MAX_ATTEMPTS; i++) {
      if (Date.now() >= deadline) break;
      await sleep(LOCK_POLL_INTERVAL_MS);
      const cached = await peekResult();
      if (cached !== undefined) return cached;
      let stillHeld: string | null;
      try {
        stillHeld = await withTimeout(redis.get(key), 'get');
      } catch {
        // Transient get failure → keep waiting on the cache instead of
        // stampeding upstream.
        continue;
      }
      if (stillHeld === null) {
        // Holder released (or vanished — heartbeat stopped firing and the
        // short TTL expired). They may have just written the cache between
        // our peek above and this check, so one final peek closes the race.
        const finalPeek = await peekResult();
        if (finalPeek !== undefined) return finalPeek;
        lockDisappeared = true;
        break;
      }
    }

    if (lockDisappeared && !takeoverAttempted) {
      // Vanished-holder takeover: re-enter the outer loop to attempt a fresh
      // SET NX. If we win, we run execute ourselves; if a peer beat us to
      // it, we fall back into the poll loop against the new owner.
      takeoverAttempted = true;
      continue;
    }
    break;
  }

  // We waited long enough and never saw a result. Surface a transient error
  // so the client retries — by then either the cache is populated (success
  // path) or the failure cache is populated (4xx path).
  const err: Error & { status?: number; oauth_error?: string } = new Error(
    'Concurrent refresh in progress',
  );
  err.status = 503;
  err.oauth_error = 'temporarily_unavailable';
  throw err;
}

/** Test seam for resetting module state. */
export function __resetForTests(): void {
  clientPromise = null;
}

import type {
  AuthorizationCode,
  AuthorizationCodeModel,
  Client,
  Token,
  User,
} from 'oauth2-server';
import {
  getClients,
  getTokens,
  getRefreshTokens,
  getRefreshResults,
  getRefreshFailures,
  getAuthorizationCodes,
  getClientRegisterHeaders,
  getClientAuthContexts,
  ClientRegisterHeadersRecord,
  ClientAuthContextRecord,
  RefreshToken,
  RefreshResult,
  RefreshFailure,
} from './kv-store';

class Model implements AuthorizationCodeModel {
  getClient: (
    clientId: string,
    clientSecret: string,
  ) => Promise<Client | undefined> = async (clientId) => {
    return getClients().get(clientId);
  };
  saveClient: (client: Client) => Promise<Client> = async (client) => {
    await getClients().set(client.id, client);
    return client;
  };
  saveClientRegisterHeaders: (
    clientId: string,
    headers: Record<string, string>,
  ) => Promise<ClientRegisterHeadersRecord> = async (clientId, headers) => {
    const record: ClientRegisterHeadersRecord = {
      headers,
      createdAt: Date.now(),
    };
    await getClientRegisterHeaders().set(clientId, record);
    return record;
  };
  getClientRegisterHeaders: (
    clientId: string,
  ) => Promise<ClientRegisterHeadersRecord | undefined> = async (clientId) => {
    return getClientRegisterHeaders().get(clientId);
  };
  saveClientAuthContext: (
    clientId: string,
    context: Omit<ClientAuthContextRecord, 'createdAt' | 'updatedAt'>,
  ) => Promise<ClientAuthContextRecord> = async (clientId, context) => {
    const existing = await getClientAuthContexts().get(clientId);
    const now = Date.now();
    const record: ClientAuthContextRecord = {
      ...context,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
    await getClientAuthContexts().set(clientId, record);
    return record;
  };
  getClientAuthContext: (
    clientId: string,
  ) => Promise<ClientAuthContextRecord | undefined> = async (clientId) => {
    return getClientAuthContexts().get(clientId);
  };
  deleteClientAuthContext: (clientId: string) => Promise<boolean> = async (
    clientId,
  ) => {
    return getClientAuthContexts().delete(clientId);
  };
  saveToken: (token: Token) => Promise<Token> = async (token) => {
    await getTokens().set(token.accessToken, token);
    return token;
  };
  deleteToken: (token: Token) => Promise<boolean> = async (token) => {
    return getTokens().delete(token.accessToken);
  };
  saveRefreshToken: (token: RefreshToken) => Promise<RefreshToken> = async (
    token,
  ) => {
    await getRefreshTokens().set(token.refreshToken, token);
    return token;
  };
  deleteRefreshToken: (token: RefreshToken) => Promise<boolean> = async (
    token,
  ) => {
    return getRefreshTokens().delete(token.refreshToken);
  };

  validateScope: (
    user: User,
    client: Client,
    scope: string,
  ) => Promise<string> = (user, client, scope) => {
    // For demo purposes, accept all scopes
    return Promise.resolve(scope);
  };
  verifyScope: (token: Token, scope: string) => Promise<boolean> = () => {
    // For demo purposes, accept all scopes
    return Promise.resolve(true);
  };
  getAccessToken: (accessToken: string) => Promise<Token | undefined> = async (
    accessToken,
  ) => {
    const token = await getTokens().get(accessToken);
    return token;
  };
  getRefreshToken: (refreshToken: string) => Promise<RefreshToken | undefined> =
    async (refreshToken) => {
      return getRefreshTokens().get(refreshToken);
    };
  saveAuthorizationCode: (
    code: AuthorizationCode,
  ) => Promise<AuthorizationCode> = async (code) => {
    await getAuthorizationCodes().set(code.authorizationCode, code);
    return code;
  };
  getAuthorizationCode: (
    code: string,
  ) => Promise<AuthorizationCode | undefined> = async (code) => {
    return getAuthorizationCodes().get(code);
  };
  revokeAuthorizationCode: (code: AuthorizationCode) => Promise<boolean> =
    async (code) => {
      return getAuthorizationCodes().delete(code.authorizationCode);
    };

  // Source-code analysis of Hydra v1.11.x confirmed `token_inactive` upstream
  // errors are triggered by *refresh-token-reuse detection* — once Hydra sees
  // the same RT twice (laptop wake, multiple Cursor windows, network blip
  // mid-rotation) it revokes the entire chain and the user must re-auth.
  // Returning the cached new pair instead of forwarding the stale RT upstream
  // is the only thing keeping these clients from being kicked.
  //
  // 7 days catches the long-tail of "user opens Cursor after a multi-day
  // pause" scenarios — post-deploy logs of #234 still showed ~30/hr cliffs
  // dominated by clients presenting RTs from beyond the previous 24h
  // window. Hydra's own RT lifespan is 30d; 7d sits comfortably inside
  // that and bounds storage growth (one entry per rotation × 7d ≈ ~50MB
  // at current traffic). The cached access token still carries its own
  // 1h `expires_at`, so a late cache hit returns an AT the client will
  // need to refresh again with the cached new RT — the chain holds
  // forward without re-auth.
  private static REFRESH_RESULT_TTL_MS = 7 * 24 * 60 * 60_000;

  saveRefreshResult: (
    oldRefreshToken: string,
    result: RefreshResult,
  ) => Promise<void> = async (oldRefreshToken, result) => {
    await getRefreshResults().set(
      oldRefreshToken,
      result,
      Model.REFRESH_RESULT_TTL_MS,
    );
  };

  getRefreshResult: (
    oldRefreshToken: string,
  ) => Promise<RefreshResult | undefined> = async (oldRefreshToken) => {
    return getRefreshResults().get(oldRefreshToken);
  };

  // 4xx rejections won't recover — upstream has invalidated the token.
  // 10 min is plenty to absorb retry storms without keeping stale entries
  // around if a misbehaving client genuinely re-auths and starts over.
  private static REFRESH_FAILURE_TTL_MS = 10 * 60_000;

  saveRefreshFailure: (
    refreshToken: string,
    detail: RefreshFailure,
  ) => Promise<void> = async (refreshToken, detail) => {
    await getRefreshFailures().set(
      refreshToken,
      detail,
      Model.REFRESH_FAILURE_TTL_MS,
    );
  };

  getRefreshFailure: (
    refreshToken: string,
  ) => Promise<RefreshFailure | undefined> = async (refreshToken) => {
    return getRefreshFailures().get(refreshToken);
  };
}

