      height: 48px;
      margin-right: 1rem;
      border-radius: 8px;
      object-fit: contain;
    }

    .alert {
      margin: 0;
      font-size: 1.5rem;
      font-weight: 400;
      margin: 1rem 0;
      text-align: center;
    }

    .description {
      color: var(--text-color-secondary);
    }

    .client-info {
      border: 1px solid var(--border-color);
      border-radius: 6px;
      padding: 1rem 1rem 0.5rem;
      margin-bottom: 1.5rem;
