      text-decoration: underline;
    }

    .detail-value.small {
      font-size: 0.8em;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      gap: 1rem;
      margin-top: 2rem;
    }

    .button {
      padding: 0.65rem 1rem;
      border-radius: 6px;
      font-weight: 500;
      cursor: pointer;
      border: none;
      font-size: 1rem;
    }

    .button-primary {
      background-color: rgb(0 229 153 / 1);
      color: rgb(26 26 26 / 1);
    }

