  </style>
</head>
<body>
  <div class="container">
    <div class="precard">
      <a class="header" href="/" target="_blank">
        <img src="https://neon.com/brand/neon-logomark-dark-color.svg" alt="Neon MCP" class="logo">
      </a>
    </div>
    <div class="card">
      <h2 class="alert"><strong>MCP Client Authorization Request</strong></h2>
      <div class="client-info">
        <div class="client-detail">
          <div class="detail-label">Name:</div>
          <div class="detail-value">${clientName}</div>
        </div>${websiteHtml}${redirectUrisHtml}
      </div>
      <p class="description">
        This MCP client is requesting to be authorized on Neon MCP Server.
        If you approve, you will be redirected to complete the authentication.
      </p>
      <form method="POST" action="/api/authorize" id="authorize-form">
        <input type="hidden" name="state" value="${he.escape(state)}" />
        <div class="scope-section">
          <div class="scope-section-title">Permissions:</div>
          ${renderScopeSection(requestedScopes, defaultReadOnly)}
        </div>
        <div class="actions">
          <button type="button" class="button button-secondary" onclick="window.history.back()">Cancel</button>
          <button type="submit" class="button button-primary">Approve</button>
        </div>
      </form>
    </div>
  </div>
  <script>
    function updateUrlScope() {
      var writeCheckbox = document.querySelector('.scope-checkbox');
      var scopes = ['read'];
      if (writeCheckbox && writeCheckbox.checked) {
        scopes.push('write');
      }
      var url = new URL(window.location.href);
      url.searchParams.set('scope', scopes.join(' '));
      window.history.replaceState({}, '', url.toString());
    }

    var writeCheckbox = document.querySelector('.scope-checkbox');
    if (writeCheckbox) {
      writeCheckbox.addEventListener('change', updateUrlScope);
    }
  </script>
</body>
</html>
`;
  return new NextResponse(html, {
    headers: { 'Content-Type': 'text/html' },
  });
};

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const requestParams = parseAuthRequest(searchParams);
    // Parse resource URI early so malformed values fail at authorize time.
    let resourceGrant: GrantContext = { ...DEFAULT_GRANT };
    let resourceReadOnlyQueryParam: string | null = null;
    try {
      resourceGrant = resolveGrantFromResourceUri(requestParams.resource);
      resourceReadOnlyQueryParam = resolveQueryParamReadOnly(
        searchParams,
        requestParams.resource,
      );
    } catch {
      return NextResponse.json(
        {
          error: 'invalid_target',
          error_description: 'Invalid resource parameter',
        },
        { status: 400 },
      );
    }

    const clientId = requestParams.clientId;
    const client = await model.getClient(clientId, '');

    logger.info('Authorize request', {
      clientId,
      redirectUri: requestParams.redirectUri,
      responseType: requestParams.responseType,
      scope: requestParams.scope,
    });

    const savedRegisterHeaders = await model.getClientRegisterHeaders(clientId);
    const savedHeaders = savedRegisterHeaders?.headers ?? {};

    const defaultReadOnly = isReadOnly({
      queryParamValue: resourceReadOnlyQueryParam,
      headerValue:
        request.headers.get('x-read-only') ?? savedHeaders['x-read-only'],
    });
    const requestedScopes =
      requestParams.scope.length > 0 ? requestParams.scope : ['read', 'write'];
    const grantWrite = !defaultReadOnly && hasWriteScope(requestedScopes);
    const effectiveScopes = resolveGrantedScopes({
      requestedScopes,
      grantWrite,
    });

    if (!client) {
      logger.warn('Client not found', { clientId });
      return NextResponse.json(
        {
          error: 'invalid_client',
          error_description: 'Invalid client ID',
        },
        { status: 400 },
      );
    }

    if (
      requestParams.responseType === undefined ||
      !client.response_types.includes(requestParams.responseType)
    ) {
      logger.warn('Invalid response type', {
        clientId,
        providedResponseType: requestParams.responseType,
        supportedResponseTypes: client.response_types,
      });
      return NextResponse.json(
        {
          error: 'unsupported_response_type',
          error_description: 'Invalid response type',
        },
        { status: 400 },
      );
    }

    if (
      requestParams.redirectUri === undefined ||
      !matchesRedirectUri(requestParams.redirectUri, client.redirect_uris)
    ) {
      logger.warn('Invalid redirect URI', {
        clientId: requestParams.clientId,
        providedRedirectUri: requestParams.redirectUri,
        registeredRedirectUris: client.redirect_uris,
      });
      return NextResponse.json(
        {
          error: 'invalid_request',
          error_description: 'Invalid redirect URI',
        },
        { status: 400 },
      );
    }

    await model.saveClientAuthContext(clientId, {
      grant: resourceGrant,
      scope: effectiveScopes,
      readOnly: !hasWriteScope(effectiveScopes),
    });

    return renderApprovalDialog(
      client,
      btoa(JSON.stringify(requestParams)),
      effectiveScopes,
      defaultReadOnly,
    );
  } catch (error: unknown) {
    return handleOAuthError(error, 'Authorization error');
  }
}

export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData();
    const state = formData.get('state') as string;
    const selectedScopes = formData.getAll('scopes') as string[];

    if (!state) {
      return NextResponse.json(
        {
          error: 'invalid_request',
          error_description: 'Invalid state',
        },
        { status: 400 },
      );
    }

    // Filter to only valid scopes (read is always included via hidden input)
    const validScopes = selectedScopes.filter((s) =>
      SUPPORTED_SCOPES.includes(s as (typeof SUPPORTED_SCOPES)[number]),
    );
    if (validScopes.length === 0) {
      return NextResponse.json(
        {
          error: 'invalid_scope',
          error_description: 'No valid scopes selected',
        },
        { status: 400 },
      );
    }

    const requestParams = JSON.parse(atob(state)) as DownstreamAuthRequest;
    const grantWrite = hasWriteScope(validScopes);
    const grantedScopes = resolveGrantedScopes({
      requestedScopes: requestParams.scope,
      grantWrite,
    });

    requestParams.scope = grantedScopes;
    const grant = requestParams.resource
      ? resolveGrantFromResourceUri(requestParams.resource)
      : { ...DEFAULT_GRANT };
    await model.saveClientAuthContext(requestParams.clientId, {
      grant,
      scope: grantedScopes,
      readOnly: !hasWriteScope(grantedScopes),
    });

    // Re-encode state with updated scopes
    const updatedState = btoa(JSON.stringify(requestParams));
    const authUrl = await upstreamAuth(updatedState);
    return NextResponse.redirect(authUrl.href);
  } catch (error: unknown) {
    return handleOAuthError(error, 'Authorization error');
  }
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    },
  });
}

import { CallToolResult } from '@modelcontextprotocol/sdk/types.js';
import { Api, NeonAuthIntegration } from '../../neon-client';
import { resolveNeonAuthBranchId } from './neon-auth-branch';
import { fetchNeonAuthConfigurableSettings } from './neon-auth-settings-snapshot';
import { ToolHandlerExtraParams } from '../types';

type Props = {
  projectId: string;
  branchId?: string;
};

function integrationPayload(int: NeonAuthIntegration) {
  const payload: Record<string, unknown> = {
    auth_provider: int.auth_provider,
    auth_provider_project_id: int.auth_provider_project_id,
    branch_id: int.branch_id,
    db_name: int.db_name,
    created_at: int.created_at,
    owned_by: int.owned_by,
    jwks_url: int.jwks_url,
    base_url: int.base_url,
  };
  if (int.transfer_status !== undefined) {
    payload.transfer_status = int.transfer_status;
  }
  return payload;
}

export async function handleGetNeonAuthConfig(
  { projectId, branchId }: Props,
  neonClient: Api<unknown>,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  _extra: ToolHandlerExtraParams,
): Promise<CallToolResult> {
  const resolvedBranchId = await resolveNeonAuthBranchId(
    projectId,
    branchId,
    neonClient,
  );

  const integrationRes = await neonClient.getNeonAuth(
    projectId,
    resolvedBranchId,
  );
  if (integrationRes.status !== 200) {
    return {
      isError: true,
      content: [
        {
          type: 'text',
          text:
            integrationRes.status === 404
              ? 'Neon Auth is not provisioned for this branch (HTTP 404). Use provision_neon_auth first.'
              : `Failed to load Neon Auth integration (${integrationRes.status} ${integrationRes.statusText}).`,
        },
      ],
    };
  }

  const [{ settings, errors }, branchRes] = await Promise.all([
    fetchNeonAuthConfigurableSettings(neonClient, projectId, resolvedBranchId),
    neonClient.getProjectBranch(projectId, resolvedBranchId),
  ]);

  const integration = integrationRes.data;
  const branch_name =
    branchRes.status === 200 ? branchRes.data.branch.name : null;

  const body: Record<string, unknown> = {
    project_id: projectId,
    branch_id: resolvedBranchId,
    branch_name,
    base_url: integration.base_url ?? null,
    jwks_url: integration.jwks_url,
    db_name: integration.db_name,
    integration: integrationPayload(integration),
    ...settings,
  };
  if (Object.keys(errors).length > 0) {
    body._errors = errors;
  }

  return {
    content: [
      {
        type: 'text',
        text: `Neon Auth configuration:\n\`\`\`json\n${JSON.stringify(body, null, 2)}\n\`\`\``,
      },
    ],
  };
}

import type { Api } from '../../neon-client';
import { getDefaultBranch } from './utils';

export async function resolveNeonAuthBranchId(
  projectId: string,
  branchId: string | undefined,
  neonClient: Api<unknown>,
): Promise<string> {
  if (branchId) {
    return branchId;
  }
  const defaultBranch = await getDefaultBranch(projectId, neonClient);
  return defaultBranch.id;
}

import { test, expect } from '@playwright/test';

type RegisterResponse = {
  client_id: string;
  client_secret: string;
};

const VALID_REGISTER_PAYLOAD = {
  client_name: 'E2E OAuth Client',
  client_uri: 'https://example.com',
  redirect_uris: ['http://127.0.0.1:55667/callback'],
  grant_types: ['authorization_code', 'refresh_token'],
  response_types: ['code'],
  token_endpoint_auth_method: 'none',
};

async function registerClient(
  request: {
    post: (
      url: string,
      options?: { data?: unknown; headers?: Record<string, string> },
    ) => Promise<{
      status: () => number;
      json: () => Promise<unknown>;
    }>;
  },
  headers: Record<string, string> = {},
): Promise<RegisterResponse> {
  const registerResponse = await request.post('/api/register', {
    data: VALID_REGISTER_PAYLOAD,
    headers,
  });
  expect(registerResponse.status()).toBe(200);
  return (await registerResponse.json()) as RegisterResponse;
}

function extractWriteCheckbox(html: string): string {
  const match = html.match(
    /<input[\s\S]*?name="scopes"[\s\S]*?value="write"[\s\S]*?class="scope-checkbox"[\s\S]*?\/>/,
  );
  expect(match).toBeTruthy();
  return match![0];
}

test.describe('OAuth register and authorize contract', () => {
  test('registered client is accepted by authorize route', async ({
    request,
  }) => {
    const registerBody = await registerClient(request);
    expect(registerBody.client_id).toBeTruthy();
    expect(registerBody.client_secret).toBeTruthy();

    const authorizeResponse = await request.get('/api/authorize', {
      params: {
        response_type: 'code',
        client_id: registerBody.client_id,
        redirect_uri: VALID_REGISTER_PAYLOAD.redirect_uris[0],
        scope: 'read write',
        state: 'e2e-state',
      },
      maxRedirects: 0,
    });

    expect(authorizeResponse.status()).toBe(200);
  });

  test('register with no read-only headers keeps Full access checked by default', async ({
    request,
  }) => {
    const registerBody = await registerClient(request);

    const authorizeResponse = await request.get('/api/authorize', {
      params: {
        response_type: 'code',
        client_id: registerBody.client_id,
        redirect_uri: VALID_REGISTER_PAYLOAD.redirect_uris[0],
        scope: 'read write',
        state: 'e2e-state',
      },
      maxRedirects: 0,
    });

    expect(authorizeResponse.status()).toBe(200);
    const body = await authorizeResponse.text();
    const writeCheckbox = extractWriteCheckbox(body);
    expect(writeCheckbox).toContain('checked');
  });

  test('register x-read-only=true defaults Full access to unchecked on authorize', async ({
    request,
  }) => {
    const registerBody = await registerClient(request, {
      'x-read-only': 'true',
    });

    const authorizeResponse = await request.get('/api/authorize', {
      params: {
        response_type: 'code',
        client_id: registerBody.client_id,
        redirect_uri: VALID_REGISTER_PAYLOAD.redirect_uris[0],
        scope: 'read write',
        state: 'e2e-state',
      },
      maxRedirects: 0,
    });

    expect(authorizeResponse.status()).toBe(200);
    const body = await authorizeResponse.text();
    const writeCheckbox = extractWriteCheckbox(body);
    expect(writeCheckbox).not.toContain('checked');
  });

  test('unknown client is rejected by authorize route', async ({ request }) => {
    const authorizeResponse = await request.get('/api/authorize', {
      params: {
        response_type: 'code',
        client_id: 'missing-client-id',
        redirect_uri: VALID_REGISTER_PAYLOAD.redirect_uris[0],
        scope: 'read write',
        state: 'e2e-state',
      },
    });

    expect(authorizeResponse.status()).toBe(400);
    const body = (await authorizeResponse.json()) as {
      error: string;
      error_description: string;
    };
    expect(body.error).toBe('invalid_client');
    expect(body.error_description).toContain('Invalid client ID');
  });
});

/**
 * E2E tests for the docs-only (no-auth) MCP endpoint.
 *
 * The strict docs-only mode (?category=docs with no other category and no
 * projectId) bypasses OAuth entirely so the docs tools can be embedded
 * anonymously. These tests run real HTTP requests against the dev server
 * and assert that:
 *  - No WWW-Authenticate header is returned
 *  - The MCP initialize handshake succeeds without an Authorization header
 *  - tools/list returns only the docs tools
 *  - Any other category combination still requires auth (401)
 */

import { test, expect, type APIResponse } from '@playwright/test';
import { DOCS_FIXTURE_MARKER } from './docs-fixture.js';

const MCP_HEADERS = {
  'Content-Type': 'application/json',
  Accept: 'application/json, text/event-stream',
};

type JsonRpcRequest = {
  jsonrpc: '2.0';
  id: number | string;
  method: string;
  params?: Record<string, unknown>;
};

const initializeRequest: JsonRpcRequest = {
  jsonrpc: '2.0',
  id: 1,
  method: 'initialize',
  params: {
    protocolVersion: '2025-03-26',
    capabilities: {},
    clientInfo: { name: 'docs-only-e2e', version: '1.0.0' },
  },
};

// The MCP streamable transport may answer with either a JSON body or an
// SSE stream depending on negotiation. Parse both.
async function readJsonRpcMessages(
  response: APIResponse,
): Promise<Array<Record<string, unknown>>> {
  const contentType = response.headers()['content-type'] ?? '';
  const body = await response.text();

  if (contentType.includes('text/event-stream')) {
    const messages: Array<Record<string, unknown>> = [];
    for (const line of body.split('\n')) {
      const trimmed = line.trim();
      if (trimmed.startsWith('data:')) {
        const dataPart = trimmed.slice('data:'.length).trim();
        if (!dataPart) continue;
        messages.push(JSON.parse(dataPart));
      }
    }
    return messages;
  }

  if (!body) return [];
  const parsed = JSON.parse(body);
  return Array.isArray(parsed) ? parsed : [parsed];
}

test.describe('Docs-only MCP endpoint (no OAuth)', () => {
  test('initialize succeeds without Authorization header on ?category=docs', async ({
    request,
  }) => {
    const response = await request.post('/mcp?category=docs', {
      headers: MCP_HEADERS,
      data: initializeRequest,
    });

    expect(
      response.status(),
      `expected 2xx but got ${response.status()}: ${await response.text()}`,
    ).toBeLessThan(300);
    expect(response.headers()['www-authenticate']).toBeUndefined();

    const messages = await readJsonRpcMessages(response);
    const initResult = messages.find((m) => m.id === 1);
    expect(initResult).toBeDefined();
    expect(initResult).toMatchObject({
      jsonrpc: '2.0',
      result: expect.objectContaining({
        serverInfo: expect.objectContaining({ name: 'mcp-server-neon' }),
      }),
    });
  });

  test('tools/list returns only the docs tools', async ({ request }) => {
    const response = await request.post('/mcp?category=docs', {
      headers: MCP_HEADERS,
      data: {
        jsonrpc: '2.0',
        id: 2,
        method: 'tools/list',
        params: {},
      },
    });
    expect(response.status()).toBeLessThan(300);
    expect(response.headers()['www-authenticate']).toBeUndefined();

    const messages = await readJsonRpcMessages(response);
    const listResult = messages.find((m) => m.id === 2) as
      | { result?: { tools?: Array<{ name: string }> } }
      | undefined;
    expect(listResult?.result?.tools).toBeDefined();

    const toolNames = listResult!.result!.tools!.map((t) => t.name).sort();
    expect(toolNames).toEqual(['get_doc_resource', 'list_docs_resources']);
  });

  // Reads the docs index from the fixture server that `playwright.config.ts`
  // points NEON_DOCS_INDEX_URL at, so this stays deterministic and off the
  // network while still exercising the real handler and fetch.
  test('tools/call list_docs_resources returns the markdown index', async ({
    request,
  }) => {
    const response = await request.post('/mcp?category=docs', {
      headers: MCP_HEADERS,
      data: {
        jsonrpc: '2.0',
        id: 3,
        method: 'tools/call',
        params: { name: 'list_docs_resources', arguments: {} },
      },
    });
    expect(response.status()).toBeLessThan(300);

    const messages = await readJsonRpcMessages(response);
    const callResult = messages.find((m) => m.id === 3) as
      | {
          result?: {
            content?: Array<{ type: string; text?: string }>;
            isError?: boolean;
          };
        }
      | undefined;
    expect(callResult?.result).toBeDefined();
    expect(callResult!.result!.isError).not.toBe(true);
    expect(callResult!.result!.content?.[0]?.type).toBe('text');
    // Matching the fixture's marker proves the index was fetched and returned,
    // rather than the tool answering with an error string or an empty body.
    expect(callResult!.result!.content?.[0]?.text).toContain(
      DOCS_FIXTURE_MARKER,
    );
  });

  test('mixed categories still require auth', async ({ request }) => {
    const response = await request.post('/mcp?category=docs,querying', {
      headers: MCP_HEADERS,
      data: initializeRequest,
    });

    expect(response.status()).toBe(401);
    expect(response.headers()['www-authenticate']).toBeTruthy();
  });

  test('docs category combined with projectId still requires auth', async ({
    request,
  }) => {
    const response = await request.post(
      '/mcp?category=docs&projectId=proj-123',
      {
        headers: MCP_HEADERS,
        data: initializeRequest,
      },
    );

    expect(response.status()).toBe(401);
    expect(response.headers()['www-authenticate']).toBeTruthy();
  });
});

import { test, expect } from '@playwright/test';

test.describe('MCP runtime response integrity regression', () => {
  test('non-MCP API routes keep returning valid responses after MCP traffic', async ({
    request,
  }) => {
    /**
     * Why this test exists:
     * - We previously saw an intermittent failure where API routes started failing with:
     *   "No response is returned from route handler..."
     * - The failure was reported to happen after MCP traffic had already touched the runtime.
     *
     * This test intentionally exercises MCP first, then validates regular API routes still
     * return valid HTTP responses and JSON bodies.
     */

    // Trigger MCP code paths first. Unauthorized is expected in this API-only test.
    for (let i = 0; i < 5; i += 1) {
      const mcpResponse = await request.get('/mcp');
      expect([401, 405]).toContain(mcpResponse.status());
    }

    // The list-tools route was our easiest reproducer for the no-response regression.
    const listTools = await request.get(
      '/api/list-tools?projectId=proj-regression-check',
    );
    expect(listTools.status()).toBe(200);
    const listToolsBody = await listTools.json();
    expect(Array.isArray(listToolsBody.tools)).toBe(true);

    // Also verify a second non-MCP route to catch cross-route runtime corruption.
    const health = await request.get('/api/health');
    expect(health.status()).toBe(200);
    const healthBody = await health.json();
    expect(healthBody.status).toBe('ok');
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';

describe('NEON_MCP_DISABLE_ANALYTICS', () => {
  afterEach(() => {
    vi.resetModules();
    vi.unstubAllEnvs();
    vi.doUnmock('@segment/analytics-node');
  });

  it('does not construct the Segment client when set to 1', async () => {
    vi.resetModules();
    vi.stubEnv('NEON_MCP_DISABLE_ANALYTICS', '1');
    const ctor = vi.fn();
    vi.doMock('@segment/analytics-node', () => ({
      Analytics: class {
        constructor() {
          ctor();
        }
        identify() {}
        track() {}
        flush() {
          return Promise.resolve();
        }
      },
    }));

    const { identify, track } = await import('../analytics/analytics');
    track({ userId: 'user-1', event: 'tool_call' });
    identify(
      { id: 'user-1', name: 'Ada', email: 'ada@example.com', isOrg: false },
      {},
    );

    expect(ctor).not.toHaveBeenCalled();
  });
});
